  "nexy.resp.services.0": "Yapay zeka entegrasyonu, özel yazılım geliştirme, mobil uygulama ve siber güvenlik alanlarında profesyonel çözümler sunuyoruz. Hangi alanla ilgileniyorsunuz?",
