  "team.join.title": "私たちのチームに参加しましょう",
  "team.member.muhammed.bio": "Fun Technology の創設者である Muhammed Erbay は、テクノロジーを誰もがアクセスでき便利なものにするというビジョンを持って会社を率いています。",
