  "projects.nexy.desc": "趣科技基于人工智能的数字助理。为企业和用户提供智能指南。",
  "projects.quakesafe.desc": "灾难安全技术的新时代。在地震期间和地震后拯救生命的智能系统。",
  "projects.soon.desc": "我们将继续致力于令人兴奋的新项目。",
  "projects.soon.title": "更多即将推出",
  "projects.view": "审查项目",
  "quakesafe.cta.button": "抢先体验",
  "quakesafe.cta.desc": "技术不仅仅是为了让生活更轻松，更是为了保护生活。",
  "quakesafe.cta.title": "我们正在建设一个更安全的未来",
  "quakesafe.features.1.desc": "在地震波到达前几秒收到紧急警报。",
  "quakesafe.features.1.title": "即时警报",
  "quakesafe.features.10.desc": "在紧急情况下分享您的健康状况和血型。",
  "quakesafe.features.10.title": "健康追踪",
  "quakesafe.features.11.desc": "查看您所在地区的历史地震数据和风险。",
  "quakesafe.features.11.title": "过去的分析",
  "quakesafe.features.12.desc": "一个将有需要的人和可以提供帮助的人聚集在一起的平台。",
  "quakesafe.features.12.title": "团结网络",
  "quakesafe.features.2.desc": "灾难期间实时查看您所爱的人所在的位置。",
  "quakesafe.features.2.title": "位置追踪",
  "quakesafe.features.3.desc": "即时到达最近的装配中心和安全区域。",
  "quakesafe.features.3.title": "安全区域",
  "quakesafe.features.4.desc": "将所有家庭成员纳入一个网络并跟踪他们的状态。",
  "quakesafe.features.4.title": "家庭团体",
  "quakesafe.features.5.desc": "即使互联网中断，也能访问重要指南和地图。",
  "quakesafe.features.5.title": "离线模式",
  "quakesafe.features.6.desc": "利用人工智能进行损害风险预测和区域安全分析。",
  "quakesafe.features.6.title": "人工智能分析",
  "quakesafe.features.7.desc": "当基站出现故障时，设备之间能够进行通信。",
  "quakesafe.features.7.title": "网状网络",
  "quakesafe.features.8.desc": "确保您的重要文件和健康数据安全。",
  "quakesafe.features.8.title": "云备份",
  "quakesafe.features.9.desc": "只需单击一下即可向当局报告瓦砾下人员的位置。",
  "quakesafe.features.9.title": "快速通知",
  "quakesafe.features.desc": "灾难发生之前、期间和之后所需的所有工具都位于一个平台上。",
  "quakesafe.features.title": "综合防护网",
  "quakesafe.hero.desc": "人工智能和传感器网络带来的地震安全革命。在几秒钟都至关重要的时刻，您最大的支持者。",
  "quakesafe.hero.title": "不用害怕地震，有了 QuakeSafe 确保安全",
  "reviews.desc": "了解我们的业务合作伙伴通过 Fun Technology 实现转型的故事。",
  "reviews.r1.name": "艾哈迈德·耶尔马兹",
  "reviews.r1.text": "作为小型企业主，您提供的软件解决方案是提高我们运营效率的救星。这确实超出了我的预期。",
  "reviews.r2.name": "泽内普·卡亚",
  "reviews.r2.text": "AI 集成绝对令人难以置信！通过自动化业务流程，我们节省了大量时间。",
  "reviews.r3.name": "穆拉特·德米尔",
  "reviews.r3.text": "这项技术彻底改变了我们的数据分析流程。这些见解是如此深刻，以至于我们现在做出决策时更加自信。",
  "reviews.r4.name": "埃利夫·沙欣",
  "reviews.r4.text": "作为项目经理，该工具对于确保跨团队协调非常宝贵。用户友好的界面非常棒！",
  "reviews.r5.name": "卡内尔·厄兹坎",
  "reviews.r5.text": "他们的开发过程的速度和质量令人惊叹。我们能够按时收到项目，同时保持卓越的质量标准。",
  "reviews.r6.name": "塞林·艾丁",
  "reviews.r6.text": "这个平台改变了我们管理数字业务的方式。这项技术是如此现代化和令人印象深刻，以至于我们整个团队都感到惊讶。",
  "reviews.title": "我们的客户怎么说？",
  "reviews.verified": "已验证客户",
