const dicts: Record<Lang, Dict> = { tr, en, de, fr, es, az, ru, ar, it, pt, ja, zh };

interface Ctx {
  lang: Lang;
  setLang: (l: Lang) => void;
  t: (key: string) => string;
}

const LangCtx = createContext<Ctx>({ lang: "tr", setLang: () => {}, t: (k) => k });

export function LanguageProvider({ children }: { children: ReactNode }) {
  const [lang, setLangState] = useState<Lang>("tr");

  useEffect(() => {
    if (typeof window !== "undefined") {
      const stored = localStorage.getItem("lang") as Lang | null;
      if (stored) {
        setLangState(stored);
      } else {
        const browserLang = navigator.language.split("-")[0] as Lang;
        const supported: Lang[] = ["tr", "en", "de", "fr", "es", "az", "ru", "ar", "it", "pt", "ja", "zh"];
        if (supported.includes(browserLang)) {
          setLangState(browserLang);
        } else {
          setLangState("en");
        }
      }
    }
  }, []);

  useEffect(() => {
    if (typeof document !== "undefined") {
      document.documentElement.lang = lang;
      const pageTitle = t("meta.title");
      if (pageTitle && pageTitle !== "meta.title") {
        document.title = pageTitle;
      }
    }
  }, [lang]);

  const setLang = (l: Lang) => {
    setLangState(l);
    if (typeof window !== "undefined") localStorage.setItem("lang", l);
  };

  const t = (key: string) => dicts[lang]?.[key] ?? dicts.tr[key] ?? key;

  return <LangCtx.Provider value={{ lang, setLang, t }}>{children}</LangCtx.Provider>;
}

export const useLang = () => useContext(LangCtx);
